<script setup lang="ts">import { ref } from "vue"; import { getReport } from "../api"; const today = new Date().toISOString().slice(0, 10); const from = ref(today); const to = ref(today); const report = ref<Awaited<ReturnType<typeof getReport>> | null>(null); const error = ref(""); const money = (value: number) => new Intl.NumberFormat("es-ES", { style: "currency", currency: "EUR" }).format(value / 100); async function load() { try { report.value = await getReport(from.value, to.value); } catch (reason) { error.value = (reason as Error).message; } }</script><template><section><header><div><p class="eyebrow">TPV</p><h1>Informes</h1></div></header><form class="filter-bar" @submit.prevent="load"><label>Desde <input v-model="from" type="date" /></label><label>Hasta <input v-model="to" type="date" /></label><button>Consultar</button></form><p v-if="error" class="feedback error">{{ error }}</p><section v-if="report" class="payment-summary"><article class="metric green"><span>Cobrado</span><strong>{{ money(report.paidCents) }}</strong></article><article class="metric amber"><span>Reembolsado</span><strong>{{ money(report.refundedCents) }}</strong></article><article class="metric blue"><span>Neto</span><strong>{{ money(report.netCents) }}</strong></article></section></section></template>